import 'package:flutter/material.dart';
import '../../../models/customer_medicine.dart';
import '../../../models/customer_payment.dart';
import '../../../models/regular_customer.dart';
import '../../../services/customer_service.dart';
import '../widgets/customer_payment_card.dart';
import 'add_customer_screen.dart';

class CustomerDetailsScreen extends StatefulWidget { final String customerId; const CustomerDetailsScreen({super.key, required this.customerId}); @override State<CustomerDetailsScreen> createState() => _CustomerDetailsScreenState(); }
class _CustomerDetailsScreenState extends State<CustomerDetailsScreen> {
  final _medicineName = TextEditingController(); final _medicineNotes = TextEditingController(); final _description = TextEditingController(); final _total = TextEditingController(); final _paid = TextEditingController(text: '0'); final _paymentNotes = TextEditingController();
  Future<void> _refresh() async { if (mounted) setState(() {}); }
  @override void dispose() { _medicineName.dispose(); _medicineNotes.dispose(); _description.dispose(); _total.dispose(); _paid.dispose(); _paymentNotes.dispose(); super.dispose(); }
  Future<void> _addMedicine() async { if (_medicineName.text.trim().isEmpty) return; final m = CustomerMedicine(id: DateTime.now().microsecondsSinceEpoch.toString(), customerId: widget.customerId, medicineName: _medicineName.text.trim(), notes: _medicineNotes.text.trim(), createdAt: DateTime.now()); await CustomerService.instance.addFrequentMedicine(m); _medicineName.clear(); _medicineNotes.clear(); await _refresh(); }
  Future<void> _addPayment() async { final total = double.tryParse(_total.text.trim()); final paid = double.tryParse(_paid.text.trim()); if (_description.text.trim().isEmpty || total == null || paid == null || total < 0 || paid < 0 || paid > total) { ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Enter a description and valid amounts. Paid amount cannot exceed total.'))); return; } final p = CustomerPayment(id: DateTime.now().microsecondsSinceEpoch.toString(), customerId: widget.customerId, description: _description.text.trim(), totalAmount: total, paidAmount: paid, createdAt: DateTime.now(), notes: _paymentNotes.text.trim()); await CustomerService.instance.addPayment(p); _description.clear(); _total.clear(); _paid.text = '0'; _paymentNotes.clear(); await _refresh(); }
  Future<void> _showAddMedicine() async { _medicineName.clear(); _medicineNotes.clear(); await showDialog<void>(context: context, builder: (ctx) => AlertDialog(title: const Text('Frequently purchased medicine'), content: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [TextField(controller: _medicineName, decoration: const InputDecoration(labelText: 'Medicine name')), TextField(controller: _medicineNotes, decoration: const InputDecoration(labelText: 'Notes (optional)'))])), actions: [TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Cancel')), FilledButton(onPressed: () async { await _addMedicine(); if (ctx.mounted) Navigator.pop(ctx); }, child: const Text('Save'))])); }
  Future<void> _showAddPayment() async { _description.clear(); _total.clear(); _paid.text = '0'; _paymentNotes.clear(); await showDialog<void>(context: context, builder: (ctx) => AlertDialog(title: const Text('Add payment record'), content: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [TextField(controller: _description, decoration: const InputDecoration(labelText: 'Description')), TextField(controller: _total, keyboardType: const TextInputType.numberWithOptions(decimal: true), decoration: const InputDecoration(labelText: 'Total amount (₹)')), TextField(controller: _paid, keyboardType: const TextInputType.numberWithOptions(decimal: true), decoration: const InputDecoration(labelText: 'Paid amount (₹)')), TextField(controller: _paymentNotes, decoration: const InputDecoration(labelText: 'Notes (optional)'))])), actions: [TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Cancel')), FilledButton(onPressed: () async { try { await _addPayment(); if (ctx.mounted) Navigator.pop(ctx); } catch (e) { if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('Could not save payment: $e'))); } }, child: const Text('Save'))])); }
  @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Customer details')), body: FutureBuilder<RegularCustomer?>(future: CustomerService.instance.getCustomerById(widget.customerId), builder: (context, snap) { if (snap.connectionState == ConnectionState.waiting) return const Center(child: CircularProgressIndicator()); final customer = snap.data; if (customer == null) return const Center(child: Text('Customer not found.')); return FutureBuilder<List<dynamic>>(future: Future.wait([CustomerService.instance.getFrequentMedicines(widget.customerId), CustomerService.instance.getPayments(widget.customerId), CustomerService.instance.getOutstandingBalance(widget.customerId)]), builder: (context, data) { if (data.connectionState == ConnectionState.waiting) return const Center(child: CircularProgressIndicator()); if (data.hasError) return Center(child: Text('Could not load details: ${data.error}')); final medicines = data.data![0] as List<CustomerMedicine>; final payments = data.data![1] as List<CustomerPayment>; final balance = data.data![2] as double; return ListView(padding: const EdgeInsets.all(16), children: [Card(child: ListTile(title: Text(customer.name, style: Theme.of(context).textTheme.titleLarge), subtitle: Text([if (customer.phone.isNotEmpty) customer.phone, if (customer.notes.isNotEmpty) customer.notes].join('\n')), trailing: IconButton(icon: const Icon(Icons.edit_outlined), onPressed: () async { await Navigator.push(context, MaterialPageRoute(builder: (_) => AddCustomerScreen(customer: customer))); await _refresh(); }))), Card(child: ListTile(title: const Text('Outstanding balance'), titleTextStyle: Theme.of(context).textTheme.titleMedium, trailing: Text('₹${balance.toStringAsFixed(2)}', style: TextStyle(fontWeight: FontWeight.bold, color: balance > 0 ? Colors.red : Colors.green)))), const SizedBox(height: 12), Row(children: [Expanded(child: Text('Frequently purchased medicines', style: Theme.of(context).textTheme.titleMedium)), IconButton(onPressed: _showAddMedicine, icon: const Icon(Icons.add_circle_outline))]), if (medicines.isEmpty) const Text('No medicines recorded.') else ...medicines.map((m) => ListTile(leading: const Icon(Icons.medication_outlined), title: Text(m.medicineName), subtitle: m.notes.isEmpty ? null : Text(m.notes), trailing: IconButton(icon: const Icon(Icons.delete_outline), onPressed: () async { await CustomerService.instance.deleteFrequentMedicine(m.id); await _refresh(); }))), const Divider(height: 28), Row(children: [Expanded(child: Text('Payment records', style: Theme.of(context).textTheme.titleMedium)), IconButton(onPressed: _showAddPayment, icon: const Icon(Icons.add_circle_outline))]), if (payments.isEmpty) const Text('No payment records.') else ...payments.map((p) => CustomerPaymentCard(payment: p, onDelete: () async { await CustomerService.instance.deletePayment(p.id); await _refresh(); }))]); }); }));
}
